import * as THREE from './vendor/three.module.js';
export function createDriftSmoke(scene){
 const canvas=document.createElement('canvas');canvas.width=canvas.height=64;const ctx=canvas.getContext('2d'),gradient=ctx.createRadialGradient(32,32,2,32,32,32);gradient.addColorStop(0,'#ffffffaa');gradient.addColorStop(1,'#ffffff00');ctx.fillStyle=gradient;ctx.fillRect(0,0,64,64);const map=new THREE.CanvasTexture(canvas),puffs=Array.from({length:12},()=>{const material=new THREE.SpriteMaterial({map,color:'#c1ccd4',transparent:true,opacity:0,depthWrite:false}),sprite=new THREE.Sprite(material);sprite.visible=false;scene.add(sprite);return {sprite,age:2,distance:0,x:0};});let clock=0,index=0;
 return {update(s,dt,quality){clock+=dt;if(s.drifting&&clock>.065){clock=0;const puff=puffs[index++%puffs.length];puff.age=0;puff.distance=s.distance;puff.x=s.x+(index%2?-.65:.65);}for(const puff of puffs){puff.age+=dt;const active=puff.age<.8&&s.mode==='playing'&&(quality.name!=='low'||puffs.indexOf(puff)%3===0);puff.sprite.visible=active;if(!active)continue;puff.sprite.position.set(puff.x,.3+puff.age*.6,(s.distance-puff.distance)+1.3);puff.sprite.scale.setScalar(.4+puff.age*1.2);puff.sprite.material.opacity=(1-puff.age/.8)*.28;}}};
}
